-- ===== สถานที่ท่องเที่ยวและที่พักเพิ่มเติม (24 โรงแรม · 27 สถานที่/งาน · 702 เที่ยวบิน) =====
-- เพิ่มผ่านตารางชั่วคราว แล้วค่อยใส่เฉพาะแถวที่ยังไม่มี → รันซ้ำได้ ไม่เกิดข้อมูลซ้ำ
-- รูปภาพทั้งหมดจาก Unsplash (ใช้ฟรีตาม Unsplash License)

DROP TEMPORARY TABLE IF EXISTS tmp_hotels, tmp_rooms, tmp_events, tmp_tickets, tmp_flights;
CREATE TEMPORARY TABLE tmp_hotels (name VARCHAR(150), city VARCHAR(100), country VARCHAR(100), address VARCHAR(255), description TEXT, star_rating TINYINT, image_url VARCHAR(500));
CREATE TEMPORARY TABLE tmp_rooms (hotel VARCHAR(150), name VARCHAR(100), capacity INT, price_per_night DECIMAL(10,2), total_rooms INT, image_url VARCHAR(500));
CREATE TEMPORARY TABLE tmp_events (name VARCHAR(150), category VARCHAR(20), city VARCHAR(100), country VARCHAR(100), venue VARCHAR(150), description TEXT, start_date DATE, end_date DATE, image_url VARCHAR(500));
CREATE TEMPORARY TABLE tmp_tickets (event VARCHAR(150), name VARCHAR(100), price DECIMAL(10,2), quantity_total INT);
CREATE TEMPORARY TABLE tmp_flights (airline VARCHAR(100), flight_no VARCHAR(20), origin VARCHAR(10), destination VARCHAR(10), depart_at DATETIME, arrive_at DATETIME, seat_class VARCHAR(10), price DECIMAL(10,2), seats INT);






SELECT t.name, t.city, t.country, t.address, t.description, t.star_rating, t.image_url FROM tmp_hotels t
WHERE NOT EXISTS (SELECT 1 FROM hotels h WHERE h.name = t.name);

SELECT h.id, t.name, t.capacity, t.price_per_night, t.total_rooms, t.image_url FROM tmp_rooms t JOIN hotels h ON h.name = t.hotel
WHERE NOT EXISTS (SELECT 1 FROM rooms r WHERE r.hotel_id = h.id AND r.name = t.name);

SELECT t.name, t.category, t.city, t.country, t.venue, t.description, t.start_date, t.end_date, t.image_url FROM tmp_events t
WHERE NOT EXISTS (SELECT 1 FROM events e WHERE e.name = t.name);

SELECT e.id, t.name, t.price, t.quantity_total, 0 FROM tmp_tickets t JOIN events e ON e.name = t.event
WHERE NOT EXISTS (SELECT 1 FROM event_tickets x WHERE x.event_id = e.id AND x.name = t.name);

SELECT t.airline, t.flight_no, t.origin, t.destination, t.depart_at, t.arrive_at, t.seat_class, t.price, t.seats, t.seats FROM tmp_flights t
WHERE NOT EXISTS (SELECT 1 FROM flights f WHERE f.flight_no = t.flight_no AND f.depart_at = t.depart_at AND f.seat_class = t.seat_class);

DROP TEMPORARY TABLE tmp_hotels, tmp_rooms, tmp_events, tmp_tickets, tmp_flights;

